    lhs = parts[0]
    rhs = parts[1]
    if "'" in rhs:
        terminal_rules[rhs.strip("'")].append(lhs)
    else:
        rhs_parts = rhs.split(' ')
        binary_rules[(rhs_parts[0], rhs_parts[1])].append(lhs)

