            for B in set_B:
                for C in set_C:
                    if (B, C) in binary_rules:
                        P[length-1][i].update(binary_rules[(B, C)])

# Check if 'S' is in the set for the entire string (length n, starting at index 0)
if 'S' in P[n-1][0]:
    print("Yes")
else:
    print("No")

